selector {
  display: flex; /* block | inline | inline-block | grid | none */
}

selector {
  position: absolute; /* static | relative | fixed | sticky */
  top: 0; inset-inline-end: 0;
}

.container {
  display: flex;
  justify-content: space-between; /* center | flex-start | flex-end | space-around */
}

.container {
  display: flex;
  align-items: center; /* stretch | flex-start | flex-end | baseline */
}

.container {
  display: flex;
  flex-direction: column; /* row | row-reverse | column-reverse */
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 16px;
}

.container {
  display: flex; /* أو grid */
  gap: 16px;      /* أو: gap: 24px 12px (صفوف أعمدة) */
}

.dropdown {
  position: absolute; /* شرط عمل z-index */
  z-index: 50;
}

.table-wrapper {
  overflow-x: auto; /* visible | hidden | scroll | auto */
}

.box {
  margin: 16px;              /* الكل */
  margin: 8px 16px;          /* رأسي أفقي */
  margin-inline: auto;       /* توسيط كتلة بعرض محدد */
}

.button {
  padding: 10px 24px; /* رأسي أفقي — وصفة الأزرار */
}

.card {
  border: 1px solid #e5e0f0;
  border-radius: 12px;
}

.card { border-radius: 12px; }
.avatar { border-radius: 50%; }
.pill { border-radius: 999px; }

.card {
  box-shadow: 0 8px 24px rgb(0 0 0 / 0.12);
  /* x y blur (spread) color */
}

.hero {
  width: 100%;
  max-width: 640px;   /* قيّد ولا تجمّد */
  min-height: 200px;  /* حد أدنى لا قفص */
}

.container {
  max-width: 1100px;
  margin-inline: auto;
  padding-inline: 16px;
}

*, *::before, *::after {
  box-sizing: border-box; /* سطر بداية كل مشروع */
}

body { color: #17151d; }
.muted { color: rgb(0 0 0 / 0.55); }
.icon { fill: currentColor; }

html { font-size: 16px; }
p  { font-size: 1.0625rem; }
h1 { font-size: clamp(1.8rem, 4vw, 3rem); }

body {
  font-family: "Cairo", "Segoe UI", system-ui, sans-serif;
}
code { font-family: "JetBrains Mono", monospace; }

h2   { font-weight: 700; }
.semibold { font-weight: 600; }
p    { font-weight: 400; }

a {
  text-decoration: underline;
  text-underline-offset: 3px; /* نجاة الحروف العربية النازلة */
}

.hero {
  background-image:
    linear-gradient(rgb(0 0 0/0) 40%, rgb(0 0 0/.7)),
    url("hero.jpg");
  background-size: cover;
}

.hero {
  background-image: url("team.jpg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.card img {
  width: 100%;
  height: 180px;      /* ارتفاع موحد للشبكة */
  object-fit: cover;  /* ملء بلا تشويه */
}

.disabled { opacity: 0.5; pointer-events: none; }
.fade { opacity: 0; transition: opacity 0.3s; }
.fade.show { opacity: 1; }

.card {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.card:hover { transform: translateY(-4px); }

@keyframes fade-up {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: none; }
}
.panel { animation: fade-up 0.3s ease both; }

.card { transition: border-color 0.2s; }
.card:hover { border-color: #7c5cff; }
.btn:active { transform: scale(0.97); }

/* الجوال أولًا: الأساس بلا شرط */
.grid { display: grid; gap: 16px; }

@media (min-width: 768px) {
  .grid { grid-template-columns: 1fr 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; }
}

:root {
  --accent: #7c5cff;
  --radius: 12px;
}
.dark { --accent: #a78bfa; }  /* الثيم = قيم جديدة فقط */

.card {
  border-radius: var(--radius);
  border-color: var(--accent);
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.latin-label {
  text-transform: uppercase;
  letter-spacing: 0.05em; /* لاتيني فقط! */
}
/* العربية: لا تباعد أبدًا */

.placeholder { visibility: hidden; } /* خفي والمكان محجوز */

/* المثلث: */
/* display:none    → لا وجود ولا مساحة */
/* visibility:hidden → مساحة بلا ظهور ولا نقر */
/* opacity:0        → شبح ينقر وتحركه CSS */

:is(header, nav, footer) a:hover {
  color: #7c5cff;
}

/* بدل: header a:hover, nav a:hover, footer a:hover */

:where(header, nav, footer) a {
  color: gray;   /* أولوية = 0، سهلة التجاوز */
}

footer a { color: blue; }  /* تتغلّب عليها بمحدّد بسيط جدًا */

section:has(.featured) { border: 2px solid #7c5cff; }

.field:has(input:invalid) { border-color: #ff4d4f; }

h1:has(+ h2) { margin-bottom: 0.25rem; }

.slot { container-type: inline-size; }

@container (width > 400px) {
  .card { display: flex; gap: 16px; }
}

.card h2 { font-size: clamp(1rem, 5cqi, 2rem); }

@layer reset, base, components, utilities;

@layer reset { * { margin: 0; padding: 0; } }
@layer components { .btn { padding: 8px 16px; } }
@layer utilities { .text-center { text-align: center; } }

.card {
  padding: 16px;

  h2 { font-size: 1.25rem; }   /* بلا & */

  &:hover { box-shadow: 0 4px 12px rgb(0 0 0 / .15); }
  &.featured { border: 2px solid #7c5cff; }

  .dark & { color: white; }    /* الأب ليس أول العنصر */
}

img, video, iframe {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
}

.square { aspect-ratio: 1 / 1; }

@property --progress {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.bar { background: linear-gradient(90deg, #7c5cff var(--progress), #e5e7eb var(--progress)); transition: --progress 0.4s; }

.box { display: block; }

@supports (display: grid) {
  .box { display: grid; }
}

@supports selector(:has(a)) {
  .nav:has(a.active) { border-bottom: 2px solid #7c5cff; }
}

.overlay {
  position: absolute;
  inset: 0;              /* top/right/bottom/left = 0 معًا */
}

.badge { position: absolute; inset: 8px auto auto 8px; }

input[type="checkbox"],
input[type="radio"] {
  accent-color: #7c5cff;
}

:root { accent-color: #7c5cff; }  /* يطبّقها على كل عناصر الصفحة الموروثة */

textarea {
  field-sizing: content; /* fixed (افتراضي) | content */
  min-height: 2.5rem;
  max-height: 12rem;
}

li {
  animation-delay: calc((sibling-index() - 1) * 80ms);
}

li {
  animation-delay: calc((sibling-count() - sibling-index()) * 80ms);
}

selector {
  text-box: trim-both cap alphabetic;
}
/* يكافئ: */
selector {
  text-box-trim: trim-both;
  text-box-edge: cap alphabetic;
}
